<?php require __DIR__.'/includes/auth.php';$p=db();$p->exec("CREATE TABLE IF NOT EXISTS blog_page_settings (id TINYINT UNSIGNED NOT NULL PRIMARY KEY, hero_kicker VARCHAR(120) NOT NULL DEFAULT 'MANUABA CRYSTALFALL', hero_title VARCHAR(255) NOT NULL DEFAULT 'Travel', hero_accent VARCHAR(120) NOT NULL DEFAULT 'Guide', hero_description TEXT NULL, hero_button_text VARCHAR(120) NOT NULL DEFAULT 'Explore Articles', hero_image VARCHAR(500) NULL, section_kicker VARCHAR(120) NOT NULL DEFAULT 'OUR BLOG', section_title VARCHAR(255) NOT NULL DEFAULT 'Latest', section_accent VARCHAR(120) NOT NULL DEFAULT 'Articles', section_description TEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$p->exec("INSERT IGNORE INTO blog_page_settings (id) VALUES (1)");$p->exec("CREATE TABLE IF NOT EXISTS blog_highlights (id INT UNSIGNED NOT NULL AUTO_INCREMENT, blog_id INT UNSIGNED NOT NULL, highlight_text VARCHAR(500) NOT NULL, sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), KEY idx_blog_highlights_blog(blog_id), CONSTRAINT fk_blog_highlights_blog FOREIGN KEY(blog_id) REFERENCES blog_posts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$id=(int)($_GET['id']??0);if($_SERVER['REQUEST_METHOD']==='POST'){admin_verify_csrf();$act=$_POST['act'];if($act==='save_hero'){$q=$p->query('SELECT hero_image FROM blog_page_settings WHERE id=1');$oldHero=$q->fetchColumn();$heroImg=admin_upload('hero_image','blog-hero',$oldHero);$st=$p->prepare('UPDATE blog_page_settings SET hero_kicker=?,hero_title=?,hero_accent=?,hero_description=?,hero_button_text=?,hero_image=?,section_kicker=?,section_title=?,section_accent=?,section_description=? WHERE id=1');$st->execute([trim($_POST['hero_kicker']??''),trim($_POST['hero_title']??''),trim($_POST['hero_accent']??''),trim($_POST['hero_description']??''),trim($_POST['hero_button_text']??''),$heroImg,trim($_POST['section_kicker']??''),trim($_POST['section_title']??''),trim($_POST['section_accent']??''),trim($_POST['section_description']??'')]);header('Location: blog.php');exit;}if($act==='save'){$id=(int)$_POST['id'];$old=null;if($id){$q=$p->prepare('SELECT cover_image FROM blog_posts WHERE id=?');$q->execute([$id]);$old=$q->fetchColumn();}$img=admin_upload('cover_image','blog',$old);$slug=admin_slug($_POST['slug']?:$_POST['title']);$pub=$_POST['published_at']?:null;if($_POST['status']==='published'&&!$pub)$pub=date('Y-m-d H:i:s');$vals=[$_POST['title'],$slug,$_POST['excerpt'],$_POST['content'],$img,$_POST['author_name'],$_POST['status'],$pub,$_POST['seo_title'],$_POST['meta_description'],$_POST['focus_keyword'],$_POST['canonical_url'],$_POST['og_image'],$_POST['schema_json']];if($id){$vals[]=$id;$p->prepare('UPDATE blog_posts SET title=?,slug=?,excerpt=?,content=?,cover_image=?,author_name=?,status=?,published_at=?,seo_title=?,meta_description=?,focus_keyword=?,canonical_url=?,og_image=?,schema_json=? WHERE id=?')->execute($vals);}else{$p->prepare('INSERT INTO blog_posts(title,slug,excerpt,content,cover_image,author_name,status,published_at,seo_title,meta_description,focus_keyword,canonical_url,og_image,schema_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($vals);$id=(int)$p->lastInsertId();}$p->prepare('DELETE FROM blog_highlights WHERE blog_id=?')->execute([$id]);$highlights=array_values(array_filter(array_map('trim',preg_split('/\R/',$_POST['highlights']??''))));$hi=$p->prepare('INSERT INTO blog_highlights(blog_id,highlight_text,sort_order) VALUES(?,?,?)');foreach(array_slice($highlights,0,10) as $i=>$text){$hi->execute([$id,$text,$i]);}header('Location: blog.php');exit;}if($act==='delete'){$q=$p->prepare('SELECT cover_image FROM blog_posts WHERE id=?');$q->execute([(int)$_POST['id']]);admin_delete_image($q->fetchColumn());$p->prepare('DELETE FROM blog_posts WHERE id=?')->execute([(int)$_POST['id']]);header('Location: blog.php');exit;}}$hero=$p->query('SELECT * FROM blog_page_settings WHERE id=1 LIMIT 1')->fetch() ?: [];
