<script>
(function(){
 const $=id=>document.getElementById(id); const form=document.querySelector('input[name="act"][value="save"]')?.closest('form'); if(!form)return;
 const field=name=>form.querySelector('[name="'+name+'"]');
 const title=field('title'),slug=field('slug'),seoTitle=field('seo_title'),keyword=field('focus_keyword'),desc=field('meta_description'),canonical=field('canonical_url'),og=field('og_image'),cover=field('cover_image'),schema=field('schema_json');
 let localCover=''; if(cover)cover.addEventListener('change',()=>{if(localCover)URL.revokeObjectURL(localCover);localCover=cover.files&&cover.files[0]?URL.createObjectURL(cover.files[0]):'';update();});
 function absoluteImage(v){v=(v||'').trim();if(!v)return '';if(/^https?:\/\//i.test(v))return v;if(v.startsWith('//'))return location.protocol+v;return new URL(v.replace(/^\//,''), location.origin+'/').href;}
 function update(){
  const t=(seoTitle?.value||'').trim()||(title?.value||'').trim(); const d=(desc?.value||'').trim()||(form.querySelector('[name="excerpt"]')?.value||'').trim(); const k=(keyword?.value||'').trim().toLowerCase();
  const slugVal=(slug?.value||'').trim()||((title?.value||'').trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''));
  const canonicalVal=(canonical?.value||'').trim()||new URL('blog-detail.php?slug='+encodeURIComponent(slugVal),location.origin+'/').href;
  const ogVal=(og?.value||'').trim(); const coverVal=localCover||absoluteImage(cover?.dataset.current||'');
  let image=localCover||absoluteImage(ogVal)||coverVal;
  const schemaVal=(schema?.value||'').trim(); let schemaValid=false; if(schemaVal){try{JSON.parse(schemaVal);schemaValid=true}catch(e){schemaValid=false}}
  const checks={
   title:[t.length>=30&&t.length<=60?'good':(t.length>0?'warn':'bad'),t.length+' characters — recommended 50–60.'],
   description:[d.length>=120&&d.length<=160?'good':(d.length>0?'warn':'bad'),d.length+' characters — recommended 140–160.'],
   keywordTitle:[k&&t.toLowerCase().includes(k)?'good':'bad',k?(t.toLowerCase().includes(k)?'Focus keyword found in title.':'Focus keyword not found in title.'):'Enter a focus keyword.'],
   keywordDescription:[k&&d.toLowerCase().includes(k)?'good':'bad',k?(d.toLowerCase().includes(k)?'Focus keyword found in description.':'Focus keyword not found in description.'):'Enter a focus keyword.'],
   canonical:[canonicalVal&&/^https?:\/\//i.test(canonicalVal)?'good':'bad',canonicalVal||'Canonical URL is missing.'],
   ogTitle:[t?'good':'bad',t?'Preview title is available.':'Article title is missing.'],
   ogDescription:[d?'good':'bad',d?'Preview description is available.':'Meta description is missing.'],
   ogImage:[image?'good':'warn',image?(ogVal?'Using OG image.':(localCover?'Using selected cover image.':'Using cover image fallback.')):'No OG image or cover image found.'],
   schema:[!schemaVal?'warn':(schemaValid?'good':'bad'),!schemaVal?'Optional: no Schema JSON-LD supplied.':(schemaValid?'Valid JSON syntax.':'Invalid JSON syntax.')]
  };
  let score=0;Object.entries(checks).forEach(([key,val])=>{const el=document.querySelector('[data-check="'+key+'"]');if(!el)return;el.classList.remove('good','warn','bad');el.classList.add(val[0]);const small=el.querySelector('small');if(small)small.textContent=val[1];if(val[0]==='good')score++;});
  $('blogSeoScore').textContent='SEO score: '+Math.round(score/9*100)+'/100';$('blogSeoScoreText').textContent=score+' of 9 checks passed.';
  $('blogPreviewTitle').textContent=t||'Article title preview';$('blogPreviewUrl').textContent=canonicalVal;$('blogPreviewDescription').textContent=d||'Meta description preview';
  const wrap=$('blogPreviewImageWrap'),fallback=$('blogPreviewImageFallback'),img=$('blogPreviewImage');if(image){img.src=image;wrap.hidden=false;fallback.hidden=true;img.onerror=()=>{wrap.hidden=true;fallback.hidden=false;fallback.textContent='Image URL cannot be loaded. Check that it is publicly accessible.';};img.onload=()=>{wrap.hidden=false;fallback.hidden=true;};}else{img.removeAttribute('src');wrap.hidden=true;fallback.hidden=false;fallback.textContent='OG image preview will appear here when an image is available.';}
 }
 if(cover){cover.dataset.current=<?=json_encode((string)($edit['cover_image']??''),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>;}
 form.querySelectorAll('input,textarea,select').forEach(el=>el.addEventListener('input',update));form.querySelectorAll('input,textarea,select').forEach(el=>el.addEventListener('change',update));update();
})();
</script>
